                    parent[(nr, nc)] = current
                    priority = nr * cols + nc
                    heapq.heappush(heap, (priority, nr, nc))

    if found:
        path = []
        current = goal
        while current != start:
            path.append(current)
            current = parent[current]
        path.append(start)
        path.reverse()
        return path
    else:
        return []
